'use strict';

const testSession=new URLSearchParams(location.search).has('test');

const $=id=>document.getElementById(id), frame=$('site-frame');

let savedSnapshot='';let activeDialogEditor=null;
let activeSave=null;const pendingPhotoUpdates=new Set();let lastPhotoFailure=null;
const snapshotSelections=new Map();
let key='',projects=[],current=null,page='',revision='',selected=null,dirty=false,history=[],historyIndex=-1,loading=false;

