function status(message,error=false){$('status').textContent=message;$('status').style.color=error?'#ffb1b1':'#b8b8b8'}

async function api(route,data){const res=await fetch(route,data===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json','X-Studio-Key':key},body:JSON.stringify(data)});const body=await res.json();if(!res.ok)throw Error(body.error||'The operation failed.');return body}

async function action(fn){try{await fn()}catch(e){status(e.message,true)}}

function buttons(){for(const id of ['save','export','preview','review','revert','duplicate-page','new-page','add-text','add-image','top-elements','top-animate','reload-page','cleanup-open','close-website','close-project','save-folder'])$(id).disabled=!current||!page;$('undo').disabled=historyIndex<=0;$('redo').disabled=historyIndex>=history.length-1;$('save-state').textContent=dirty?'Unsaved changes · Save page to keep them':current?(current.saveFolder?'Saves to linked website folder':'Choose a save folder on first Save'):'Your original files stay safe'}

async function confirmDiscard(){await waitForPhotoUpdates();if(activeSave)await activeSave;return !dirty||await askConfirm('This page has unsaved changes. Discard them and continue?')}

function projectList(){const box=$('project-list');box.replaceChildren();const showTests=$('show-test-projects').checked;const visible=projects.filter(p=>showTests||!/(?:verification|fixture|pipeline review|reference image review)/i.test(p.name));for(const p of visible){const b=document.createElement('button');b.className='project-item'+(current?.id===p.id?' active':'');const duplicates=visible.filter(x=>x.name===p.name);b.textContent=p.name+(duplicates.length>1?' · '+new Date((p.lastSaved||p.created)*1000).toLocaleString([], {month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'}):'');b.onclick=()=>action(async()=>{if(await confirmDiscard()){await openProject(p.id);$('website-dialog').close()}});box.append(b)}if(!visible.length){const empty=document.createElement('p');empty.className='hint';empty.textContent='No saved websites yet.';box.append(empty)}}

async function refreshProjects(){const s=await api('/api/session');key=s.key;projects=s.projects;projectList()}

async function openProject(id){current=await api('/api/project?id='+encodeURIComponent(id));$('project-name').textContent=current.name;if(!testSession)localStorage.setItem('studio-last-project',id);projectList();renderPages();const requested=new URL(location.href);const initialPage=requested.searchParams.get('project')===id?requested.searchParams.get('page'):null;await openPage(current.pages.includes(initialPage)?initialPage:current.pages.includes('index.html')?'index.html':current.pages[0]);status('Project opened as a safe working copy. Click an element to edit.');}

function renderPages(){const box=$('page-list');box.replaceChildren();const ordered=[...current.pages].sort((a,b)=>a==='index.html'?-1:b==='index.html'?1:a.localeCompare(b));for(const name of ordered){const b=document.createElement('button');b.className='page-item'+(name===page&&!activeDialogEditor?' active':'');b.dataset.page=name;b.textContent=name;b.title='Open '+name;b.onclick=()=>action(async()=>{if(await confirmDiscard())await openPage(name)});box.append(b)}if(!loading&&doc()?.body){for(const dialog of doc().querySelectorAll('dialog[id]')){const b=document.createElement('button');b.className='page-item'+(activeDialogEditor===dialog.id?' active':'');b.textContent=dialog.id.charAt(0).toUpperCase()+dialog.id.slice(1)+' (popup)';b.title='Edit '+dialog.id+' popup in '+page;b.onclick=()=>{activeDialogEditor=dialog.id;configureDialogEditor();renderPages();selected=null;fillInspector();status('Editing '+dialog.id+' popup. Save page updates this popup in '+page+'.')};box.append(b)}}}

async function imported(result){if(result.cancelled)return status('Folder selection cancelled.');projects.push(result);await openProject(result.id)}

$('browse').onclick=()=>action(async()=>{if(!await confirmDiscard())return;status('Choose the website folder in the folder window.');await imported(await api('/api/browse',{}))});

$('open-path').onclick=()=>action(async()=>{if(await confirmDiscard())await imported(await api('/api/open',{path:$('folder-path').value}))});


$('zip-button').onclick=()=>$('zip-input').click();

async function fileData(file){const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));return btoa(binary)}

$('zip-input').onchange=()=>action(async()=>{const f=$('zip-input').files[0];if(!f||!await confirmDiscard())return;if(f.size>30*1024*1024)throw Error('Use Open folder for ZIP files larger than 30 MB.');status('Importing website ZIP…');await imported(await api('/api/import-zip',{name:f.name,data:await fileData(f)}));$('zip-input').value=''});

function pageURL(preview=false){return (preview?current.previewOrigin:'')+'/site/'+current.id+'/'+page.split('/').map(encodeURIComponent).join('/')}

async function openPage(name){activeDialogEditor=null;if(!name)throw Error('No HTML page found.');page=name;selected=null;const result=await api('/api/page?id='+current.id+'&page='+encodeURIComponent(page));revision=result.revision;loading=true;dirty=false;history=[];historyIndex=-1;$('welcome').hidden=true;$('frame-wrap').hidden=false;frame.onload=()=>{if(!loading)return;loading=false;instrument();history=[serialize()];savedSnapshot=history[0];historyIndex=0;buttons();renderPages();syncProjectAddress()};frame.src=pageURL()+'?studio='+Date.now();buttons();}

function doc(){return frame.contentDocument}

function serialize(){const clone=doc().documentElement.cloneNode(true);clone.querySelector('#studio-edit-style')?.remove();clone.querySelector('#studio-dialog-edit-style')?.remove();clone.querySelectorAll('[data-studio-dialog-edit]').forEach(e=>{if(e.dataset.studioDialogEdit==='closed')e.removeAttribute('open');e.removeAttribute('data-studio-dialog-edit')});clone.querySelector('#studio-edit-base')?.remove();clone.querySelector('#studio-selection-overlay')?.remove();clone.removeAttribute('data-studio-drag-mode');clone.querySelectorAll('[data-studio-multiselected]').forEach(e=>e.removeAttribute('data-studio-multiselected'));clone.querySelectorAll('[data-studio-selected]').forEach(e=>e.removeAttribute('data-studio-selected'));return '<!DOCTYPE html>\n'+clone.outerHTML}

function elementPath(e){const out=[];while(e&&e!==doc().documentElement){const parent=e.parentElement;if(!parent)return null;out.unshift([...parent.children].indexOf(e));e=parent}return out}

function fromPath(path){let e=doc().documentElement;for(const n of path||[])e=e?.children[n];return e}

function instrument(){const d=doc();if(!d.querySelector('base')){const base=d.createElement('base');base.id='studio-edit-base';base.href=new URL(pageURL(),location.origin).href;d.head.prepend(base)}d.querySelector('#studio-edit-style')?.remove();const style=d.createElement('style');style.id='studio-edit-style';style.textContent=`html{scroll-behavior:auto!important}body{cursor:default!important}[data-studio-multiselected]{outline:2px solid #19b88c!important;outline-offset:3px}.reveal:not([data-studio-animation]){opacity:1!important;transform:none!important}.brand-loader{display:none!important}a,button{cursor:crosshair!important}*:not([data-studio-animation]){animation:none!important}[data-studio-animation]{animation-play-state:running!important}`;d.head.append(style);d.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();if(e.target.closest?.('#studio-selection-overlay'))return;if(suppressCanvasClick){suppressCanvasClick=false;return}if(elementClipboard){pasteTarget={x:e.clientX+d.defaultView.scrollX,y:e.clientY+d.defaultView.scrollY,project:current.id,page};pasteSequence=0;status('Paste position set. Ctrl+V or Paste places the copy here.')}let target=e.target.closest?.('[data-studio-icon]')||e.target;if(target.nodeType!==1)target=target.parentElement;if(['HTML','BODY','SCRIPT','STYLE','LINK','META','NOSCRIPT'].includes(target.tagName))return;select(target,e.shiftKey||e.ctrlKey||e.metaKey);if(elementClipboard&&pasteTarget)status('Paste position set at '+Math.round(pasteTarget.x)+', '+Math.round(pasteTarget.y)+'. Ctrl+V or Paste places the copy here.');if(target.tagName==='IMG'&&target.hasAttribute('data-studio-frame-placeholder')){frameUploadTarget=target;$('frame-photo-input').click()} },true);d.addEventListener('submit',e=>e.preventDefault(),true);d.addEventListener('keydown',keyboard,true);selected=null;alignmentSelection=[];refreshAlignment();installMovement(d);installTransformBox(d);installElementClipboard(d);installFrameDrop(d);installButtonDrop(d);installRotation(d);fillInspector();configureDialogEditor();}

let alignmentSelection=[];
function select(e,add=false){if(!add)alignmentSelection=[];if(add&&alignmentSelection.includes(e)){alignmentSelection=alignmentSelection.filter(x=>x!==e)}else{alignmentSelection=alignmentSelection.filter(x=>x.isConnected&&x.ownerDocument===doc()&&!x.contains(e)&&!e.contains(x));alignmentSelection.push(e)}refreshAlignment();if(add&&!alignmentSelection.includes(e))e=alignmentSelection.at(-1);if(!e){selected?.removeAttribute('data-studio-selected');selected=null;fillInspector();updateTransformBox();return}if(['HTML','HEAD','BODY'].includes(e.tagName))return;doc().querySelectorAll('[data-studio-selected]').forEach(x=>x.removeAttribute('data-studio-selected'));selected=e;e.setAttribute('data-studio-selected','');fillInspector();showInspectorPanel('properties');status(alignmentSelection.length>1?alignmentSelection.length+' elements selected. Align them or drag a selected item to move together.':'Selected '+e.tagName.toLowerCase()+(e.id?' #'+e.id:'')+'. Shift-click or Ctrl-click another item to add it.');}

function fillInspector(){const box=$('inspector-content');box.hidden=!selected;if(!selected){$('selection-label').textContent='Click text, an image or a section in the canvas.';return}const s=frame.contentWindow.getComputedStyle(selected);$('selection-label').textContent=selected.tagName.toLowerCase()+(selected.id?' #'+selected.id:'')+(selected.className&&typeof selected.className==='string'?' .'+selected.className.trim().split(/\s+/).slice(0,3).join('.'):'');const isImage=selected.tagName==='IMG',simple=[...selected.children].every(e=>e.tagName==='BR');$('image-section').hidden=!isImage;$('text-section').hidden=isImage;$('text-content').value=selected.innerText||selected.textContent||'';$('text-content').disabled=!simple;$('text-warning').textContent=simple?'Text edits preserve the selected element.':'This element contains nested formatting or other elements. Select the inner text element to edit without deleting its children.';$('font-size').value=parseFloat(s.fontSize)||16;$('font-weight').value=s.fontWeight;$('font-family').value='';$('line-height').value=(parseFloat(s.lineHeight)/parseFloat(s.fontSize)||1.5).toFixed(2);$('letter-spacing').value=parseFloat(s.letterSpacing)||0;$('text-color').value=hex(s.color);$('background-color').value=hex(s.backgroundColor);$('element-width').value=selected.style.width||'';$('element-height').value=selected.style.height||'';$('element-width').placeholder=Math.round(selected.getBoundingClientRect().width)+'px (current)';$('element-height').placeholder=Math.round(selected.getBoundingClientRect().height)+'px (current)';$('border-radius').value=parseFloat(s.borderTopLeftRadius)||0;$('opacity').value=Math.round(parseFloat(s.opacity)*100);$('padding').value=parseFloat(s.paddingTop)||0;$('margin').value=parseFloat(s.marginTop)||0;$('aspect-ratio').value=selected.style.aspectRatio||'auto';$('animation').value=selected.dataset.studioAnimation||'none';$('animation-duration').value=selected.dataset.studioDuration||1;$('animation-delay').value=selected.dataset.studioDelay||0;$('animation-repeat').value=selected.dataset.studioRepeat||'1';if(isImage){$('image-thumb').replaceChildren();const thumb=document.createElement('img');thumb.src=selected.src;thumb.alt='Selected image preview';$('image-thumb').append(thumb);$('image-alt').value=selected.alt||'';$('object-fit').value=s.objectFit;$('object-position').value=selected.style.objectPosition||'center'} }

function hex(value){const m=value.match(/[\d.]+/g);if(!m||m.length<3)return '#000000';return '#'+m.slice(0,3).map(x=>Math.round(Number(x)).toString(16).padStart(2,'0')).join('')}

function checkpoint(){const html=serialize();if(selected)snapshotSelections.set(html,elementPath(selected));if(history[historyIndex]!==html){history=history.slice(0,historyIndex+1);history.push(html);if(history.length>80)history.shift();historyIndex=history.length-1;dirty=html!==savedSnapshot}buttons();}

function mutate(fn,refresh=true){if(!selected)return;if(selectionPositionLocked())return lockedPositionMessage();try{fn(selected);checkpoint();if(refresh)fillInspector();updateTransformBox();status('Changed '+selected.tagName.toLowerCase()+'. Save page to keep your edits.')}catch(e){status(e.message,true)}}

function style(property,value){mutate(e=>{if(property==='color'){setEditorTextColor(e,value);return}if(value==='')e.style.removeProperty(property);else e.style.setProperty(property,value,'important')})}

function restoreSnapshot(index){if(index<0||index>=history.length)return;const path=snapshotSelections.get(history[index])||(selected?elementPath(selected):null),y=frame.contentWindow.scrollY;historyIndex=index;const d=doc();let restored=history[index];if(!/<base\b/i.test(restored)){const base='<base id="studio-edit-base" href="'+new URL(pageURL(),location.origin).href+'">';restored=restored.replace(/<head([^>]*)>/i,'<head$1>'+base)}d.open();d.write(restored);d.close();instrument();if(path&&fromPath(path))select(fromPath(path));frame.contentWindow.scrollTo(0,y);dirty=serialize()!==savedSnapshot;buttons();status('Undo / redo applied. Save page to keep this version.')}

$('undo').onclick=()=>restoreSnapshot(historyIndex-1);$('redo').onclick=()=>restoreSnapshot(historyIndex+1);

function editingText(e){return !!e.target.closest?.('input,textarea,select,[contenteditable]:not([contenteditable="false"])')}
function deleteSelected(){if(!selected?.isConnected)return;if(selectionPositionLocked())return lockedPositionMessage();snapshotSelections.set(history[historyIndex],elementPath(selected));const items=alignmentSelection.length?alignmentSelection.filter(e=>e.isConnected):[selected];for(const e of items){const style=frame.contentWindow.getComputedStyle(e);if(!['absolute','fixed'].includes(style.position)&&style.display!=='none'){const spacer=e.cloneNode(true);spacer.dataset.studioLayoutSpacer='true';spacer.setAttribute('aria-hidden','true');spacer.setAttribute('inert','');for(const n of [spacer,...spacer.querySelectorAll('*')]){n.removeAttribute('id');n.removeAttribute('data-studio-selected');n.removeAttribute('data-studio-multiselected');n.removeAttribute('autofocus');for(const attr of [...n.attributes])if(attr.name.startsWith('on'))n.removeAttribute(attr.name);n.style.setProperty('visibility','hidden','important');n.style.setProperty('pointer-events','none','important')}spacer.querySelectorAll('script,iframe,audio,video').forEach(n=>n.remove());e.replaceWith(spacer)}else e.remove()}alignmentSelection=[];selected=null;refreshAlignment();checkpoint();fillInspector();updateTransformBox();frame.contentWindow.focus();status('Deleted '+items.length+' item(s), keeping their layout space so other elements stay aligned. Undo restores them.');}
function keyboard(e){if(editingText(e)||e.target.closest?.('dialog'))return;const modifier=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();if(k==='delete'&&!modifier){if(selected){e.preventDefault();deleteSelected()}return}if(!modifier)return;if(k==='s'){e.preventDefault();action(save)}if(k==='z'){e.preventDefault();restoreSnapshot(historyIndex+(e.shiftKey?1:-1));frame.contentWindow.focus()}if(k==='y'){e.preventDefault();restoreSnapshot(historyIndex+1);frame.contentWindow.focus()}}document.addEventListener('keydown',keyboard);

$('deselect').onclick=()=>{selected?.removeAttribute('data-studio-selected');alignmentSelection=[];selected=null;refreshAlignment();fillInspector()};$('parent-element').onclick=()=>selected&&select(selected.parentElement);$('delete-element').onclick=deleteSelected;

$('text-content').onchange=()=>mutate(e=>{if([...e.children].some(c=>c.tagName!=='BR'))throw Error('Select an inner text element first.');e.textContent=$('text-content').value});

const bindings={'font-size':['font-size','px'],'font-weight':['font-weight',''],'line-height':['line-height',''],'letter-spacing':['letter-spacing','px'],'text-color':['color',''],'background-color':['background-color',''],'element-width':['width',''],'element-height':['height',''],'border-radius':['border-radius','px'],'padding':['padding','px'],'margin':['margin','px'],'object-fit':['object-fit',''],'object-position':['object-position','']};

for(const [id,[property,unit]] of Object.entries(bindings))$(id).onchange=()=>{const val=$(id).value;if(['element-width','element-height'].includes(id)&&val&&!CSS.supports(property,val)){status('Use a valid size such as auto, 100% or 300px.',true);return}style(property,val?val+unit:'')};

$('font-family').onchange=()=>{if($('font-family').value)style('font-family',$('font-family').value)};$('opacity').onchange=()=>style('opacity',Math.max(0,Math.min(100,Number($('opacity').value)))/100);$('clear-background').onclick=()=>style('background','transparent');$('circle-shape').onclick=()=>style('border-radius','50%');$('aspect-ratio').onchange=()=>{const ratio=$('aspect-ratio').value;mutate(e=>{e.style.setProperty('aspect-ratio',ratio,'important');e.style.setProperty('height','auto','important');if(e.tagName==='IMG')e.style.setProperty('object-fit','cover','important')})};

document.querySelectorAll('[data-align]').forEach(b=>b.onclick=()=>style('text-align',b.dataset.align));$('image-alt').onchange=()=>mutate(e=>e.alt=$('image-alt').value);$('replace-image').onclick=()=>$('image-input').click();

$('image-input').onchange=()=>{const file=$('image-input').files[0],target=selected;$('image-input').value='';if(file&&target?.tagName==='IMG')action(()=>uploadIntoFrame(file,target))};

$('apply-animation').onclick=()=>mutate(e=>{const preset=$('animation').value;const properties=['transform','display','opacity','clip-path','filter','letter-spacing','background-color'];if(e.dataset.studioAnimationBase){const base=JSON.parse(e.dataset.studioAnimationBase);for(const name of properties){const v=base[name];if(v?.value)e.style.setProperty(name,v.value,v.priority);else e.style.removeProperty(name)}}if(preset==='none'){e.style.setProperty('animation','none','important');for(const name of ['studioAnimation','studioDuration','studioDelay','studioRepeat','studioAnimationBase'])delete e.dataset[name];return}const computed=frame.contentWindow.getComputedStyle(e);if(!e.dataset.studioAnimationBase){const base={};for(const name of properties)base[name]={value:e.style.getPropertyValue(name),priority:e.style.getPropertyPriority(name)};e.dataset.studioAnimationBase=JSON.stringify(base)}const baseTransform=computed.transform==='none'?'':computed.transform;e.style.setProperty('--studio-letter-spacing',computed.letterSpacing);if(computed.display==='inline')e.style.setProperty('display','inline-block','important');e.style.setProperty('transform',`${baseTransform} var(--studio-motion)`,'important');let sheet=doc().querySelector('#studio-animation-styles');if(sheet&&sheet.tagName!=='STYLE'){sheet.remove();sheet=null}if(!sheet){sheet=doc().createElement('style');sheet.id='studio-animation-styles';doc().head.append(sheet)}sheet.textContent=ANIMATIONS;const duration=Math.max(.1,Math.min(30,Number($('animation-duration').value)||1)),delay=Math.max(0,Math.min(30,Number($('animation-delay').value)||0)),repeat=$('animation-repeat').value;e.dataset.studioAnimation=preset;e.dataset.studioDuration=duration;e.dataset.studioDelay=delay;e.dataset.studioRepeat=repeat;e.style.setProperty('animation','none','important');void e.offsetWidth;e.style.setProperty('animation',`studio-${preset} ${duration}s ${preset==='typewriter'?'steps(24,end)':'ease'} ${delay}s ${repeat} both`,'important')});

async function save(){if(!current||!page)return;if(!current.saveFolder){const chosen=await api('/api/save-folder',{id:current.id});if(chosen.cancelled)throw Error('Save cancelled. Choose a destination folder to save your website.');current.saveFolder=chosen.folder}if(activeSave){await activeSave;if(serialize()!==savedSnapshot)return save();return}const pid=current.id,name=page;const task=(async()=>{await waitForPhotoUpdates(pid,name);if(current?.id!==pid||page!==name)throw Error('The page changed before saving. Select the intended page and Save again.');const html=serialize(),expectedRevision=revision,editingDocument=doc();$('save').textContent='Saving…';const result=await api('/api/save',{id:pid,page:name,revision:expectedRevision,html});if(current?.id===pid&&page===name&&doc()===editingDocument){revision=result.revision;savedSnapshot=html;dirty=serialize()!==savedSnapshot;buttons();syncProjectAddress();status(result.sourceError?'Working copy saved, but original folder was NOT updated: '+result.sourceError:dirty?'Saved; newer edits still need saving.':'Saved to '+(result.source?.folder||'builder working copy')+' · '+name,!!result.sourceError);if(result.sourceError)throw Error('Original folder was NOT updated: '+result.sourceError)}})();activeSave=task;try{await task}finally{if(activeSave===task)activeSave=null;$('save').textContent='Save page'}}

$('save').onclick=()=>action(save);$('reload-page').onclick=()=>action(async()=>{if(await confirmDiscard())await openPage(page)});

$('export').onclick=()=>action(async()=>{if(!current)return;const pid=current.id;await waitForPhotoUpdates();if(serialize()!==savedSnapshot||activeSave)await save();if(current?.id!==pid||serialize()!==savedSnapshot)throw Error('The canvas changed while preparing export. Save the latest changes and export again.');status('Preparing ZIP from saved '+current.name+'…');const response=await fetch('/api/export?id='+encodeURIComponent(pid));if(!response.ok){const error=await response.json();throw Error(error.error||'Export could not be created.')}const blob=await response.blob();if(!blob.type.includes('zip'))throw Error('Export did not return a ZIP file.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(current.name.toLowerCase().replace(/[^a-z0-9_-]+/g,'-').replace(/^-|-$/g,'')||'website')+'-export.zip';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status('ZIP download started for '+current.name+'. It includes the saved page and uploaded photo files.')});

