function cloneElementSafe(source,offsetX=0,offsetY=0,template=null){const originalRect=source.getBoundingClientRect(),computed=frame.contentWindow.getComputedStyle(source),frozen=[...computed].map(name=>[name,computed.getPropertyValue(name)]);const clone=template?template.cloneNode(true):source.cloneNode(true);preserveKnownActions(clone);const idMap=new Map(),all=[clone,...clone.querySelectorAll('*')];for(const e of all){e.removeAttribute('data-studio-selected');if(e.id){const next=e.id+'-copy-'+Math.random().toString(36).slice(2,8);idMap.set(e.id,next);e.id=next}}for(const e of all)for(const attr of ['for','aria-labelledby','aria-describedby','aria-controls','href','xlink:href']){const val=e.getAttribute(attr);if(!val)continue;if(val.startsWith('#')&&idMap.has(val.slice(1)))e.setAttribute(attr,'#'+idMap.get(val.slice(1)));else if(attr.startsWith('aria-')||attr==='for')e.setAttribute(attr,val.split(/\s+/).map(x=>idMap.get(x)||x).join(' '))}for(const [name,value] of frozen)clone.style.setProperty(name,value,'important');for(const name of ['transform','translate','rotate','scale','transition','animation']){const value=source.style.getPropertyValue(name);if(value)clone.style.setProperty(name,value,source.style.getPropertyPriority(name));else clone.style.removeProperty(name)}clone.style.setProperty('position','absolute','important');clone.style.setProperty('inset','auto','important');clone.style.setProperty('left','0px','important');clone.style.setProperty('top','0px','important');clone.style.setProperty('margin','0','important');clone.style.setProperty('width',computed.width==='auto'?source.offsetWidth+'px':computed.width,'important');clone.style.setProperty('height',computed.height==='auto'?source.offsetHeight+'px':computed.height,'important');clone.style.setProperty('max-width','none','important');clone.style.setProperty('max-height','none','important');if(computed.display==='inline')clone.style.setProperty('display','inline-block','important');source.after(clone);const axes=duplicateAxes(clone);if(computed.display==='inline'&&Math.abs(axes.b)<.00001&&Math.abs(axes.c)<.00001){clone.style.setProperty('box-sizing','border-box','important');clone.style.setProperty('width',originalRect.width/Math.abs(axes.a)+'px','important');clone.style.setProperty('height',originalRect.height/Math.abs(axes.d)+'px','important')}const local=viewportVector(axes,originalRect.left-clone.getBoundingClientRect().left+offsetX,originalRect.top-clone.getBoundingClientRect().top+offsetY);clone.style.setProperty('left',local.x+'px','important');clone.style.setProperty('top',local.y+'px','important');return clone}
function duplicateSelected(){if(!selected)return;selected=cloneElementSafe(selected);select(selected);checkpoint();status('Element duplicated with new IDs. Move or resize it, then Save page.')}
