function copyCanvasElement(event){if(!selected?.isConnected)return false;const copy=selected.cloneNode(true);preserveKnownActions(copy);copy.removeAttribute('data-studio-selected');elementClipboard=copy.outerHTML;elementClipboardSource=selected;pasteSequence=0;pasteTarget=null;if(event?.clipboardData){event.clipboardData.setData('application/x-shankys-element',elementClipboard);event.clipboardData.setData('text/html',elementClipboard);event.clipboardData.setData('text/plain','Shankys element: '+elementClipboard);event.preventDefault()}status('Element copied. Click a canvas position to paste there, or paste now with a small offset.');return true}
function pasteCanvasElement(html=elementClipboard){if(!html||!current||!doc())return;const d=doc(),temp=d.createElement('template');temp.innerHTML=html;const source=temp.content.firstElementChild;if(!source)return;let anchor=elementClipboardSource?.isConnected&&elementClipboardSource.ownerDocument===d?elementClipboardSource:selected;let temporary=false;if(!anchor){source.style.setProperty('position','absolute','important');d.body.append(source);anchor=source;temporary=true}const useTarget=pasteTarget&&pasteTarget.project===current.id&&pasteTarget.page===page,step=useTarget?0:16*(++pasteSequence);const anchorRect=anchor.getBoundingClientRect();const offset=useTarget?{x:pasteTarget.x-frame.contentWindow.scrollX-anchorRect.left+step,y:pasteTarget.y-frame.contentWindow.scrollY-anchorRect.top+step}:{x:step,y:step};const pasted=cloneElementSafe(anchor,offset.x,offset.y,source);if(useTarget)placePasteOnPage(pasted,pasteTarget.x+step,pasteTarget.y+step);if(temporary)source.remove();select(pasted);checkpoint();frame.contentWindow.focus();status(useTarget?'Element pasted at your clicked canvas position.':'Element pasted with a small diagonal offset. Drag to position it.');}
function installElementClipboard(d){d.addEventListener('keydown',event=>{if(!(event.ctrlKey||event.metaKey)||editingText(event)||event.target.closest?.('dialog'))return;const k=event.key.toLowerCase();if(k==='c')copyCanvasElement();if(k==='v'&&elementClipboard){event.preventDefault();pasteCanvasElement()}if(k==='d'&&selected){event.preventDefault();duplicateSelected()}},true);d.addEventListener('copy',event=>{if(!editingText(event))copyCanvasElement(event)},true);d.addEventListener('paste',event=>{if(editingText(event))return;const data=event.clipboardData,plain=data?.getData('text/plain')||'',html=data?.getData('application/x-shankys-element')||(plain.startsWith('Shankys element: ')?plain.slice(16):'')||elementClipboard;if(html){event.preventDefault();pasteCanvasElement(html)}},true)}
