$('new-page').onclick=()=>action(async()=>{const name=await askText(current.structure==='organized-v1'?'New page name (saved under pages/):':'New page name (same folder):','new-page.html');if(!name)return;if(dirty)await save();const result=await api('/api/new-page',{id:current.id,page,name});current=result.project;projects=projects.map(p=>p.id===current.id?current:p);projectList();renderPages();await openPage(result.page);status('Blank page created. Add text/images and link to it from your other pages.')});
