$('add-image').onclick=()=>$('add-image-input').click();$('add-image-input').onchange=()=>{const file=$('add-image-input').files[0];$('add-image-input').value='';if(!file||!current)return;const target=selected,pid=current.id,name=page,d=doc();action(()=>trackPhotoUpdate(async()=>{const result=await api('/api/image',{id:pid,name:file.name,data:await fileData(file)});if(current?.id!==pid||page!==name||doc()!==d)throw Error('Photo copied but the page changed before insertion. The uploaded file is preserved.');const image=d.createElement('img');image.src='../'.repeat(name.split('/').length-1)+result.path;await image.decode();image.alt=file.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ');image.style.cssText='display:block;width:320px;max-width:100%;height:auto;border-radius:12px;';selected=target?.isConnected?target:null;insertElement(image);status('Photo added. Save or Export will keep this image.');},pid,name))};

function question(message,value,confirmation){return new Promise(resolve=>{const d=$('question-dialog');$('question-title').textContent=message;$('question-input-label').hidden=confirmation;$('question-input').value=value||'';$('question-ok').textContent=confirmation?'Confirm':'Create';const finish=result=>{d.close();resolve(result)};$('question-ok').onclick=()=>finish(confirmation?true:$('question-input').value);$('question-cancel').onclick=()=>finish(confirmation?false:null);d.oncancel=e=>{e.preventDefault();finish(confirmation?false:null)};$('question-input').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('question-ok').click()}};d.showModal();if(!confirmation){$('question-input').focus();$('question-input').select()}})}
function askText(message,value){return question(message,value,false)}function askConfirm(message){return question(message,'',true)}

