function applyFramePreset(preset){if(!selected||selected.tagName!=='IMG')return;mutate(e=>{const properties=['clip-path','border-radius','aspect-ratio','height','object-fit'];if(preset.id==='original'){const original=e.dataset.studioFrameBase?JSON.parse(e.dataset.studioFrameBase):{};for(const property of properties){const saved=original[property];if(saved?.value)e.style.setProperty(property,saved.value,saved.priority);else e.style.removeProperty(property)}delete e.dataset.studioFrame;delete e.dataset.studioFrameBase;return}if(!e.dataset.studioFrameBase){const base={};for(const property of properties)base[property]={value:e.style.getPropertyValue(property),priority:e.style.getPropertyPriority(property)};e.dataset.studioFrameBase=JSON.stringify(base)}e.dataset.studioFrame=preset.id;e.style.setProperty('clip-path',preset.clip,'important');e.style.setProperty('border-radius',preset.radius,'important');if(!['rectangle','rounded'].includes(preset.id)){e.style.setProperty('aspect-ratio',preset.ratio||'1 / 1','important');e.style.setProperty('height','auto','important')}e.style.setProperty('object-fit','cover','important')});status('Image frame applied. Adjust the focal point or Save page to keep it. Original removes the frame.')}
