const animationPresets=[["none", "Static"], ["fade", "Fade"], ["rise", "Rise"], ["slide", "Slide"], ["zoom", "Zoom"], ["pulse", "Pulse"], ["float", "Float"], ["typewriter", "Typewriter"], ["ascend", "Ascend"], ["shift", "Shift"], ["merge", "Merge"], ["block", "Block"], ["burst", "Burst"], ["bounce", "Bounce"], ["roll", "Roll"], ["skate", "Skate"], ["spread", "Spread"], ["clarify", "Clarify"]];for(const [id,name] of animationPresets){if(!$('animation').querySelector(`option[value="${id}"]`))$('animation').add(new Option(name,id))}for(const [id,name] of animationPresets){const b=document.createElement('button');b.className='preset-tile';b.dataset.animationPreset=id;b.setAttribute('aria-pressed','false');const mini=document.createElement('span');mini.className='animation-mini';mini.textContent='Abc';b.append(mini,document.createTextNode(name));b.onclick=()=>{if(!selected)return status('Select text or an element in the canvas before applying an animation.',true);$('animation').value=id;$('apply-animation').click()};$('animation-tiles').append(b)}
