function addFrameAt(preset,x,y){if(!current||!doc())return;const image=doc().createElement('img');image.src=framePlaceholder;image.alt='Empty '+preset.name.toLowerCase()+' photo frame';image.dataset.studioFramePlaceholder='true';image.style.cssText='position:absolute;display:block;left:'+Math.max(0,x)+'px;top:'+Math.max(0,y)+'px;width:240px;height:240px;object-fit:cover;z-index:3;';doc().body.append(image);select(image);applyFramePreset(preset);checkpoint();showInspectorPanel('properties');status('Frame added. Click it to upload a photo, or drop a photo file into it. Drag to position; corners resize.');return image}
for(const preset of framePresets.filter(p=>p.id!=='original')){const b=document.createElement('button');b.className='preset-tile';b.draggable=true;b.dataset.libraryFrame=preset.id;b.title='Drag '+preset.name+' frame onto canvas';const mini=document.createElement('span');mini.className='frame-mini';mini.style.clipPath=preset.clip;mini.style.borderRadius=preset.radius;b.append(mini,document.createTextNode(preset.name));b.ondragstart=event=>{event.dataTransfer.setData('application/x-shankys-frame',preset.id);event.dataTransfer.setData('text/plain','Shankys frame: '+preset.id);event.dataTransfer.effectAllowed='copy'};b.onclick=()=>addFrameAt(preset,Math.max(20,(frame.contentWindow.innerWidth-240)/2),frame.contentWindow.scrollY+100);$('frame-library').append(b)}
function uploadIntoFrame(file,target){if(!target?.isConnected||!current)return Promise.resolve();const pid=current.id,name=page,d=doc();return trackPhotoUpdate(async()=>{if(file.size>20*1024*1024)throw Error('Choose a photo smaller than 20 MB.');status('Uploading photo… Save and Export will wait for it.');const result=await api('/api/image',{id:pid,name:file.name,data:await fileData(file)});if(!target.isConnected||target.ownerDocument!==d||current?.id!==pid||page!==name||doc()!==d)throw Error('Photo copied, but its target or page changed before placement. The uploaded file is preserved.');const src='../'.repeat(name.split('/').length-1)+result.path,probe=new Image();probe.src=new URL(src,d.baseURI).href;try{await probe.decode()}catch{throw Error('The uploaded file could not be opened as an image. The original photo is unchanged.')}select(target);const wasPlaceholder=target.hasAttribute('data-studio-frame-placeholder');setPhotoSource(target,src);if(!target.alt||wasPlaceholder)target.alt=file.name.replace(/\.[^.]+$/,'').replace(/[-_]/g,' ');target.removeAttribute('data-studio-frame-placeholder');target.style.setProperty('object-fit','cover','important');checkpoint();fillInspector();updateTransformBox();status('Photo updated. Save page or Export ZIP keeps this replacement.');},pid,name)}
