function installFrameDrop(d){d.addEventListener('dragover',event=>{const types=[...(event.dataTransfer?.types||[])];if(types.includes('application/x-shankys-frame')||types.includes('Files')){event.preventDefault();event.dataTransfer.dropEffect='copy'}},true);d.addEventListener('drop',event=>{const id=event.dataTransfer?.getData('application/x-shankys-frame'),file=event.dataTransfer?.files?.[0];if(!id&&!file)return;event.preventDefault();event.stopPropagation();if(id){const preset=framePresets.find(p=>p.id===id);if(preset)addFrameAt(preset,event.clientX+frame.contentWindow.scrollX-120,event.clientY+frame.contentWindow.scrollY-120)}else if(file){let target=event.target.closest?.('img');if(!target)target=addFrameAt(framePresets.find(p=>p.id==='rectangle'),event.clientX+frame.contentWindow.scrollX-120,event.clientY+frame.contentWindow.scrollY-120);action(()=>uploadIntoFrame(file,target))}},true)}
