$('apply-image-source').onclick=()=>{const src=$('image-source').value.trim();if(!src)return status('Enter a project image path or website image URL.',true);if(/^[a-z][a-z0-9+.-]*:/i.test(src)&&!/^https?:/i.test(src))return status('Use a project image path or an HTTP(S) image URL.',true);mutate(e=>{if(e.tagName!=='IMG')return;setPhotoSource(e,src);e.removeAttribute('data-studio-frame-placeholder');lastPhotoFailure=null})};

function angleInDegrees(value){if(!value||value==='none')return 0;const part=value.trim().split(/\s+/).pop(),n=parseFloat(part)||0;return part.endsWith('grad')?n*.9:part.endsWith('rad')?n*180/Math.PI:part.endsWith('turn')?n*360:n}
function rotateElement(e,angle){if(e.hasAttribute('data-studio-locked'))return;if(!e.dataset.studioRotationBase){const computed=frame.contentWindow.getComputedStyle(e);e.dataset.studioRotationBase=JSON.stringify({raw:e.style.getPropertyValue('rotate'),priority:e.style.getPropertyPriority('rotate'),base:angleInDegrees(computed.rotate)});if(computed.display==='inline'&&!['IMG','INPUT','VIDEO','CANVAS'].includes(e.tagName)){e.dataset.studioRotationDisplay=JSON.stringify({raw:e.style.getPropertyValue('display'),priority:e.style.getPropertyPriority('display')});e.style.setProperty('display','inline-block','important')}}const base=JSON.parse(e.dataset.studioRotationBase);e.dataset.studioRotation=angle;e.style.setProperty('rotate',(base.base+angle)+'deg','important')}
$('rotation-angle').oninput=()=>mutate(e=>rotateElement(e,Number($('rotation-angle').value)||0),false);
$('reset-rotation').onclick=()=>mutate(e=>{if(e.dataset.studioRotationBase){const base=JSON.parse(e.dataset.studioRotationBase);if(base.raw)e.style.setProperty('rotate',base.raw,base.priority);else e.style.removeProperty('rotate')}if(e.dataset.studioRotationDisplay&&!e.dataset.studioMoveBase){const display=JSON.parse(e.dataset.studioRotationDisplay);if(display.raw)e.style.setProperty('display',display.raw,display.priority);else e.style.removeProperty('display')}delete e.dataset.studioRotationBase;delete e.dataset.studioRotation;delete e.dataset.studioRotationDisplay});
