function installRotation(d){let rotating=null;d.addEventListener('pointerdown',event=>{if(!event.target.dataset?.studioRotate||!selected)return;if(selectionPositionLocked()){event.preventDefault();event.stopImmediatePropagation();lockedPositionMessage();return}event.preventDefault();event.stopImmediatePropagation();const r=selected.getBoundingClientRect(),cx=r.left+r.width/2,cy=r.top+r.height/2;rotating={e:selected,cx,cy,start:Math.atan2(event.clientY-cy,event.clientX-cx),angle:Number(selected.dataset.studioRotation)||0,changed:false};try{event.target.setPointerCapture(event.pointerId)}catch{}},true);d.addEventListener('pointermove',event=>{if(!rotating)return;event.preventDefault();const a=rotating;let delta=(Math.atan2(event.clientY-a.cy,event.clientX-a.cx)-a.start)*180/Math.PI;while(delta>180)delta-=360;while(delta<-180)delta+=360;let angle=Math.round(a.angle+delta);if(event.shiftKey)angle=Math.round(angle/15)*15;rotateElement(a.e,angle);$('rotation-angle').value=angle;a.changed=true;updateTransformBox()},true);const finish=()=>{if(!rotating)return;if(rotating.changed){suppressCanvasClick=true;checkpoint();fillInspector();status('Rotation changed. Save page to keep it; Undo restores the previous angle.')}rotating=null};d.addEventListener('pointerup',finish,true);d.addEventListener('pointercancel',finish,true)}


function ensureButtonRouting(){if(doc().querySelector('#studio-button-routing'))return;const script=doc().createElement('script');script.id='studio-button-routing';script.textContent=`document.addEventListener('click',function(event){const b=event.target.closest&&event.target.closest('[data-studio-dialog]');if(!b)return;const target=document.getElementById(b.dataset.studioDialog);if(!target||target.tagName!=='DIALOG')return;event.preventDefault();event.stopImmediatePropagation();const parent=b.closest('dialog');if(parent&&parent!==target)parent.close();if(!target.open)target.showModal();},true);`;doc().head.append(script)}
