function buttonAppearance(e,shape){e.style.setProperty('display','inline-flex','important');e.style.setProperty('align-items','center','important');e.style.setProperty('justify-content','center','important');e.style.setProperty('padding','14px 26px','important');e.style.setProperty('background-color','#b91524','important');e.style.setProperty('color','#fff','important');e.style.setProperty('border','0','important');e.style.setProperty('border-radius',shape==='pill'?'999px':shape==='rounded'?'12px':'0','important');e.style.setProperty('text-decoration','none','important');e.dataset.studioButton=shape;}
