function installButtonDrop(d){d.addEventListener('dragover',event=>{if([...event.dataTransfer.types].includes('application/x-shankys-button'))event.preventDefault()},true);d.addEventListener('drop',event=>{const shape=event.dataTransfer.getData('application/x-shankys-button');if(!['rectangle','rounded','pill'].includes(shape))return;event.preventDefault();addButtonAt(shape,event.clientX+frame.contentWindow.scrollX-60,event.clientY+frame.contentWindow.scrollY-20)},true)}
$('text-to-button').onclick=()=>mutate(e=>{if(e.matches('img,video,iframe')||!e.textContent.trim())throw Error('Select text first.');let b=e;if(!e.matches('a,button')){b=doc().createElement('button');b.type='button';for(const a of [...e.attributes])b.setAttribute(a.name,a.value);const c=frame.contentWindow.getComputedStyle(e);for(const name of ['font-family','font-size','font-weight','font-style','letter-spacing','line-height'])b.style.setProperty(name,c.getPropertyValue(name),'important');while(e.firstChild)b.append(e.firstChild);e.replaceWith(b);selected=b}buttonAppearance(b,'rounded');});
const fillInspectorBeforeButtons=fillInspector;fillInspector=function(){fillInspectorBeforeButtons();if(!selected)return;const list=$('button-dialog');list.replaceChildren();for(const d of doc().querySelectorAll('dialog[id]'))list.add(new Option(d.id,d.id));$('button-action').value=selected.dataset.studioDialog?'dialog':'link';if(selected.dataset.studioDialog)list.value=selected.dataset.studioDialog};
$('apply-button-action').onclick=()=>{if($('button-action').value==='link'){$('apply-link').click();return}const id=$('button-dialog').value;if(!id)return status('This page has no dialog with an ID. Configure a link instead.',true);mutate(e=>{e.dataset.studioDialog=id;ensureButtonRouting()})};

function duplicateAxes(e){const left=e.style.getPropertyValue('left'),top=e.style.getPropertyValue('top'),lp=e.style.getPropertyPriority('left'),tp=e.style.getPropertyPriority('top'),r=e.getBoundingClientRect();e.style.setProperty('left',(parseFloat(left)||0)+100+'px','important');const x=e.getBoundingClientRect();e.style.setProperty('left',left,lp);e.style.setProperty('top',(parseFloat(top)||0)+100+'px','important');const y=e.getBoundingClientRect();e.style.setProperty('top',top,tp);return {a:(x.left-r.left)/100,b:(x.top-r.top)/100,c:(y.left-r.left)/100,d:(y.top-r.top)/100}}
function viewportVector(m,x,y){const determinant=m.a*m.d-m.b*m.c;if(Math.abs(determinant)<.00001)return {x,y};return {x:(m.d*x-m.c*y)/determinant,y:(m.a*y-m.b*x)/determinant}}

function placePasteOnPage(e,x,y){const view=frame.contentWindow,c=view.getComputedStyle(e),axes=duplicateAxes(e),rootTransform=c.transform,rotate=c.rotate,scale=c.scale,translate=c.translate;const childStyles=[...e.querySelectorAll('*')].map(child=>[child,[...view.getComputedStyle(child)].map(name=>[name,view.getComputedStyle(child).getPropertyValue(name)])]);for(const [child,properties] of childStyles)for(const [name,value] of properties)child.style.setProperty(name,value,'important');for(const [name,value] of [['rotate',rotate],['scale',scale],['translate',translate]])e.style.setProperty(name,value,'important');if(Math.abs(axes.a-1)+Math.abs(axes.d-1)+Math.abs(axes.b)+Math.abs(axes.c)>.00001){const Matrix=view.DOMMatrix,parent=new Matrix([axes.a,axes.b,axes.c,axes.d,0,0]),rotation=new Matrix().rotate(parseFloat(rotate)||0),parts=scale==='none'?[1,1]:scale.split(/\s+/).map(Number),rs=rotation.scale(parts[0]||1,parts[1]||parts[0]||1),base=rootTransform==='none'?new Matrix():new Matrix(rootTransform);e.style.setProperty('transform',rs.inverse().multiply(parent).multiply(rs).multiply(base).toString(),'important')}else if(!e.style.getPropertyValue('transform').includes('var('))e.style.setProperty('transform',rootTransform,'important');doc().body.append(e);e.style.setProperty('left','0px','important');e.style.setProperty('top','0px','important');const r=e.getBoundingClientRect(),map=duplicateAxes(e),delta=viewportVector(map,x-view.scrollX-r.left,y-view.scrollY-r.top);e.style.setProperty('left',delta.x+'px','important');e.style.setProperty('top',delta.y+'px','important');anchorPlacedElement(e,x,y);}

function syncProjectAddress(){if(!current||!page)return;const url=new URL(location.href);url.searchParams.set('project',current.id);if(page==='index.html')url.searchParams.delete('page');else url.searchParams.set('page',page);window.history.replaceState(null,'',url);}
function setPhotoSource(e,src){e.setAttribute('src',src);for(const attr of ['srcset','sizes','data-src','data-srcset'])e.removeAttribute(attr);if(e.parentElement.tagName==='PICTURE')e.parentElement.querySelectorAll('source').forEach(source=>source.remove());}
function trackPhotoUpdate(operation,pid=current?.id,name=page){lastPhotoFailure=null;const entry={pid,name};entry.promise=Promise.resolve().then(operation).catch(error=>{lastPhotoFailure={pid,name,error};throw error}).finally(()=>pendingPhotoUpdates.delete(entry));pendingPhotoUpdates.add(entry);return entry.promise;}
async function waitForPhotoUpdates(pid=current?.id,name=page){let entries;while((entries=[...pendingPhotoUpdates].filter(e=>e.pid===pid&&e.name===name)).length){status('Waiting for the photo to finish before saving…');await Promise.all(entries.map(e=>e.promise));}if(lastPhotoFailure?.pid===pid&&lastPhotoFailure?.name===name)throw Error('Photo update did not finish: '+lastPhotoFailure.error.message+' Retry the photo update before saving/exporting.');}

$('website-menu').onclick=()=>{$('website-menu-name').textContent=current?current.name:'No website open';projectList();$('save-folder-label').textContent=current?.saveFolder||'Choose a folder when saving this website.';$('website-dialog').showModal()};$('website-menu-close').onclick=()=>$('website-dialog').close();$('show-test-projects').onchange=projectList;
for(const id of ['new-website','reference-open','browse','open-path','zip-button','sample','new-page','duplicate-page'])$(id).addEventListener('click',()=>{if($('website-dialog').open)$('website-dialog').close()},true);

let cleanupReview=null,cleanupProject=null;
$('cleanup-open').onclick=()=>{cleanupProject=current?.id;cleanupReview=null;$('cleanup-files').replaceChildren();$('cleanup-status').textContent='Scan to review eligible files. No files have been moved.';$('cleanup-trash').disabled=true;$('website-dialog').close();$('cleanup-dialog').showModal()};$('cleanup-close').onclick=()=>$('cleanup-dialog').close();
$('cleanup-scan').onclick=async()=>{const button=$('cleanup-scan');button.disabled=true;try{if(!current||current.id!==cleanupProject)throw Error('Open Cleanup again for the current website.');await waitForPhotoUpdates();if(serialize()!==savedSnapshot||activeSave)await save();$('cleanup-status').textContent='Scanning saved file references…';const result=await api('/api/cleanup/scan',{id:cleanupProject});cleanupReview=result;$('cleanup-files').replaceChildren();for(const file of result.candidates){const label=document.createElement('label'),check=document.createElement('input');check.type='checkbox';check.value=file.path;check.checked=true;label.className='compact-check';label.append(check,document.createTextNode(file.path+' · '+Math.round(file.bytes/1024)+' KB'));$('cleanup-files').append(label)}$('cleanup-trash').disabled=!result.candidates.length;$('cleanup-restore').disabled=!result.trashAvailable;$('cleanup-status').textContent=result.candidates.length+' eligible unused file(s). '+result.recentProtected+' recent upload(s) protected. '+result.reasons.join(' ')}catch(e){$('cleanup-status').textContent=e.message}finally{button.disabled=false}};
$('cleanup-trash').onclick=async()=>{const button=$('cleanup-trash');button.disabled=true;try{if(!cleanupReview)throw Error('Scan first.');if(current?.id!==cleanupProject||serialize()!==savedSnapshot||pendingPhotoUpdates.size)throw Error('The canvas changed after review. Save and scan again; nothing was moved.');const paths=[...$('cleanup-files').querySelectorAll('input:checked')].map(e=>e.value);const result=await api('/api/cleanup/trash',{id:cleanupProject,token:cleanupReview.token,paths});cleanupReview=null;$('cleanup-files').replaceChildren();$('cleanup-status').textContent=result.message+' '+result.moved+' file(s) moved.';$('cleanup-restore').disabled=false}catch(e){$('cleanup-status').textContent=e.message}};
$('cleanup-restore').onclick=async()=>{try{const result=await api('/api/cleanup/restore',{id:cleanupProject});$('cleanup-status').textContent=result.restored+' file(s) restored to their original locations.';$('cleanup-restore').disabled=!result.trashAvailable;cleanupReview=null;$('cleanup-trash').disabled=true;$('cleanup-files').replaceChildren()}catch(e){$('cleanup-status').textContent=e.message}};

// Closing releases the editing canvas; saved website files remain available.
function finishCloseWebsite(){loading=false;frame.onload=null;alignmentSelection=[];selected=null;current=null;page='';revision='';dirty=false;savedSnapshot='';history=[];historyIndex=-1;snapshotSelections.clear();lastPhotoFailure=null;frame.src='about:blank';$('preview-frame').src='about:blank';$('frame-wrap').hidden=true;$('welcome').hidden=false;$('page-list').textContent='Open a website to see its pages.';$('project-name').textContent='Choose a website';$('website-menu-name').textContent='No website open';fillInspector();showInspectorPanel('design');if(!testSession)localStorage.removeItem('studio-last-project');const url=new URL(location.href);url.searchParams.delete('project');url.searchParams.delete('page');window.history.replaceState(null,'',url);buttons();projectList();status('Website closed. Your saved files are kept. Create or open another website.');$('website-dialog').showModal()}
async function requestCloseWebsite(){if(!current)return;await waitForPhotoUpdates();if(activeSave)await activeSave;if($('website-dialog').open)$('website-dialog').close();if(dirty||serialize()!==savedSnapshot){$('close-website-dialog').showModal();return}finishCloseWebsite()}
$('close-project').onclick=$('close-website').onclick=()=>action(requestCloseWebsite);
$('close-cancel').onclick=()=>$('close-website-dialog').close();
$('close-discard').onclick=()=>{$('close-website-dialog').close();finishCloseWebsite()};
$('close-save').onclick=()=>action(async()=>{await save();if(serialize()!==savedSnapshot)throw Error('New edits appeared while saving. Save again before closing.');$('close-website-dialog').close();finishCloseWebsite()});
$('welcome-open').onclick=()=>$('website-menu').click();

function refreshAlignment(){if(!doc())return;doc().querySelectorAll('[data-studio-multiselected]').forEach(e=>e.removeAttribute('data-studio-multiselected'));alignmentSelection=alignmentSelection.filter(e=>e.isConnected&&e.ownerDocument===doc());alignmentSelection.forEach(e=>e.setAttribute('data-studio-multiselected',''));$('alignment-count').textContent=alignmentSelection.length+' selected';document.querySelectorAll('[data-align-elements]').forEach(b=>b.disabled=alignmentSelection.length<2)}
for(const b of document.querySelectorAll('[data-align-elements]'))b.onclick=()=>{refreshAlignment();if(alignmentSelection.length<2)return;if(selectionPositionLocked())return lockedPositionMessage();const rects=alignmentSelection.map(e=>e.getBoundingClientRect()),left=Math.min(...rects.map(r=>r.left)),right=Math.max(...rects.map(r=>r.right)),top=Math.min(...rects.map(r=>r.top)),bottom=Math.max(...rects.map(r=>r.bottom));alignmentSelection.forEach((e,i)=>{const r=rects[i],mode=b.dataset.alignElements;let dx=0,dy=0;if(mode==='left')dx=left-r.left;if(mode==='right')dx=right-r.right;if(mode==='center')dx=(left+right-r.left-r.right)/2;if(mode==='top')dy=top-r.top;if(mode==='bottom')dy=bottom-r.bottom;if(mode==='middle')dy=(top+bottom-r.top-r.bottom)/2;moveElement(e,moveInPixels(e,e.dataset.studioMoveX,e.dataset.studioMoveUnit||'px','x')+dx,moveInPixels(e,e.dataset.studioMoveY,e.dataset.studioMoveUnit||'px','y')+dy,'px')});checkpoint();fillInspector();updateTransformBox();status('Selected elements aligned. Undo restores their previous positions.')};
$('save-folder').onclick=()=>action(async()=>{if(!current)return;const result=await api('/api/save-folder',{id:current.id});if(!result.cancelled){current.saveFolder=result.folder;$('save-folder-label').textContent=result.folder;status('Save destination: '+result.folder)}});

function visibleSwapBackground(e){let node=e;while(node){const color=frame.contentWindow.getComputedStyle(node).backgroundColor;if(color!=='transparent'&&!/^rgba\([^)]*,\s*0(?:\.0+)?\s*\)$/.test(color))return color;node=node.parentElement}return 'rgb(255, 255, 255)'}
$('swap-colors').onclick=()=>{if(!selected?.isConnected)return;const control=selected.closest('button,a[role=button],a.button');if(control&&control!==selected)select(control);mutate(e=>{const textNodes=[e,...e.querySelectorAll('*')].filter(n=>![ 'SCRIPT','STYLE','SVG','PATH' ].includes(n.tagName)&&[...n.childNodes].some(c=>c.nodeType===3&&c.textContent.trim()));const label=textNodes.find(n=>frame.contentWindow.getComputedStyle(n).display!=='none')||e;const textStyle=frame.contentWindow.getComputedStyle(label);let text=textStyle.webkitTextFillColor||textStyle.color;if(text==='transparent'||/^rgba\([^)]*,\s*0(?:\.0+)?\s*\)$/.test(text))text=textStyle.color;const background=visibleSwapBackground(e);setEditorTextColor(e,background);e.style.setProperty('background-color',text,'important')});status('Text and background colors swapped. Continue editing or use Undo to restore them.')};

function setEditorTextColor(e,color){for(const n of [e,...e.querySelectorAll('*')].filter(n=>n===e||[...n.childNodes].some(c=>c.nodeType===3&&c.textContent.trim()))){if(color)n.style.setProperty('color',color,'important');else n.style.removeProperty('color');n.style.setProperty('-webkit-text-fill-color','currentColor','important')}}

function anchorPlacedElement(e,x,y){const d=doc(),view=frame.contentWindow;const old=e.style.getPropertyValue('pointer-events'),priority=e.style.getPropertyPriority('pointer-events');e.style.setProperty('pointer-events','none','important');const hit=d.elementFromPoint(x-view.scrollX,y-view.scrollY);if(old)e.style.setProperty('pointer-events',old,priority);else e.style.removeProperty('pointer-events');const parent=hit?.closest('article,section,main,[data-studio-container]');if(!parent||parent===e||e.contains(parent))return;if(view.getComputedStyle(parent).position==='static')parent.style.setProperty('position','relative');parent.append(e);e.style.setProperty('left','0px','important');e.style.setProperty('top','0px','important');const r=e.getBoundingClientRect(),map=duplicateAxes(e),delta=viewportVector(map,x-view.scrollX-r.left,y-view.scrollY-r.top);e.style.setProperty('left',delta.x/Math.max(1,parent.clientWidth)*100+'%','important');e.style.setProperty('top',delta.y+'px','important');e.dataset.studioAnchored='container'}

$('ungroup-element').onclick=()=>action(async()=>{const wrapper=selected;if(!wrapper?.isConnected)return;if(selectionPositionLocked())return lockedPositionMessage();if(wrapper.hasAttribute('data-studio-responsive-row'))throw Error('This row keeps its text and button aligned across screen sizes. Select the text or button inside it to edit; keep this responsive row together.');if(!['DIV','SPAN','P','FIGURE'].includes(wrapper.tagName)||!wrapper.children.length)throw Error('Select an outer text or layout container with Select parent first. Buttons, links and page sections keep their actions.');if(wrapper.id||[...wrapper.attributes].some(a=>a.name.startsWith('on'))||wrapper.querySelector('script,iframe'))throw Error('This wrapper has an identifier or attached behavior. Choose a plain inner container to keep its connections intact.');const parent=wrapper.parentElement,view=frame.contentWindow;const records=[...wrapper.childNodes].filter(n=>n.nodeType===1||n.nodeType===3&&n.textContent.trim()).map(n=>{if(n.nodeType===3){const span=doc().createElement('span');n.replaceWith(span);span.append(n);n=span}const r=n.getBoundingClientRect(),c=view.getComputedStyle(n);return {e:n,x:r.left,y:r.top,w:r.width,h:r.height,styles:['font-family','font-size','font-weight','font-style','line-height','letter-spacing','color','text-align','text-transform','background-color','border-radius','padding','box-sizing'].map(k=>[k,c.getPropertyValue(k)])}});if(!records.length)return;if(view.getComputedStyle(parent).position==='static')parent.style.setProperty('position','relative');for(const a of records){for(const [name,value] of a.styles)a.e.style.setProperty(name,value,'important');parent.insertBefore(a.e,wrapper);for(const [name,value] of Object.entries({position:'absolute',left:'0px',top:'0px',margin:'0px',width:a.w+'px',height:a.h+'px','box-sizing':'border-box',translate:'none',transform:'none'}))a.e.style.setProperty(name,value,'important');for(const key of ['studioMoveBase','studioMoveX','studioMoveY','studioMoveUnit'])delete a.e.dataset[key];const r=a.e.getBoundingClientRect(),delta=viewportVector(duplicateAxes(a.e),a.x-r.left,a.y-r.top);a.e.style.setProperty('left',delta.x/Math.max(1,parent.clientWidth)*100+'%','important');a.e.style.setProperty('top',delta.y+'px','important');a.e.dataset.studioAnchored='container'}wrapper.remove();select(records[0].e);alignmentSelection=records.map(a=>a.e);refreshAlignment();checkpoint();fillInspector();updateTransformBox();status('Outer container removed; its contents are kept and selected. Undo restores the wrapper.');});

const designIcons={Location:'<path d="M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0Z"/><circle cx="12" cy="10" r="2.5"/>',Phone:'<path d="m5 3 4 1 1 5-3 2a15 15 0 0 0 6 6l2-3 5 1 1 4c-1 5-7 3-11 0S1 8 5 3Z"/>',Email:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m2 5 10 8L22 5"/>',Clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',Calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 2v6m10-6v6M3 11h18"/>',Search:'<circle cx="10" cy="10" r="7"/><path d="m15 15 7 7"/>',Check:'<path d="m4 12 5 5L20 6"/>',Close:'<path d="m5 5 14 14M19 5 5 19"/>',Menu:'<path d="M3 5h18M3 12h18M3 19h18"/>','Arrow right':'<path d="M3 12h18m-7-7 7 7-7 7"/>',Heart:'<path d="M12 21 3 12C-3 4 7-1 12 6c5-7 15-2 9 6Z"/>',Star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1Z"/>'};
const designShapes={Rectangle:{width:'140px',height:'90px'},Square:{width:'100px',height:'100px'},Rounded:{width:'140px',height:'90px',borderRadius:'18px'},Circle:{width:'100px',height:'100px',borderRadius:'50%'},Oval:{width:'150px',height:'90px',borderRadius:'50%'},Triangle:{width:'110px',height:'100px',clipPath:'polygon(50% 0,100% 100%,0 100%)'},Diamond:{width:'110px',height:'110px',clipPath:'polygon(50% 0,100% 50%,50% 100%,0 50%)'},Line:{width:'160px',height:'4px'}};
function addDesignPrimitive(kind,name){if(!current||!doc())return status('Open a website first.',true);const d=doc();let e;if(kind==='icon'){e=d.createElementNS('http://www.w3.org/2000/svg','svg');e.setAttribute('viewBox','0 0 24 24');e.setAttribute('fill','none');e.setAttribute('stroke','currentColor');e.setAttribute('stroke-width','1.8');e.setAttribute('stroke-linecap','round');e.setAttribute('stroke-linejoin','round');e.setAttribute('role','img');e.setAttribute('aria-label',name);e.dataset.studioIcon=name;e.innerHTML=designIcons[name];e.style.cssText='width:48px;height:48px;color:#a6111b;display:block;'}else{e=d.createElement('div');e.dataset.studioShape=name;e.setAttribute('role','img');e.setAttribute('aria-label',name+' shape');Object.assign(e.style,{backgroundColor:'#a6111b',...designShapes[name]})}const x=frame.contentWindow.scrollX+55,y=frame.contentWindow.scrollY+120;Object.assign(e.style,{position:'absolute',left:x+'px',top:y+'px',zIndex:'3'});d.body.append(e);anchorPlacedElement(e,x,y);select(e);checkpoint();showInspectorPanel('properties');status(name+' added. Change its color or dimensions in Design.');}
for(const [name,paths] of Object.entries(designIcons)){const b=document.createElement('button');b.className='preset-tile';b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>';b.append(document.createTextNode(name));b.onclick=()=>addDesignPrimitive('icon',name);$('icon-library').append(b)}
for(const [name,shape] of Object.entries(designShapes)){const b=document.createElement('button');b.className='preset-tile';const mini=document.createElement('span');mini.className='shape-mini';Object.assign(mini.style,{borderRadius:shape.borderRadius||'0',clipPath:shape.clipPath||'none',...(name==='Line'?{height:'4px',marginTop:'20px',marginBottom:'20px'}:{})});b.append(mini,document.createTextNode(name));b.onclick=()=>addDesignPrimitive('shape',name);$('shape-library').append(b)}

function configureDialogEditor(){const d=doc();d.querySelector('#studio-dialog-edit-style')?.remove();for(const e of d.querySelectorAll('[data-studio-dialog-edit]')){if(e.dataset.studioDialogEdit==='closed')e.removeAttribute('open');e.removeAttribute('data-studio-dialog-edit')}if(!activeDialogEditor)return;const target=d.getElementById(activeDialogEditor);if(!target||target.tagName!=='DIALOG'){activeDialogEditor=null;return}target.dataset.studioDialogEdit=target.hasAttribute('open')?'open':'closed';target.setAttribute('open','');const style=d.createElement('style');style.id='studio-dialog-edit-style';style.textContent='body> :not([data-studio-dialog-edit]):not(#studio-selection-overlay){display:none!important}body{min-height:100vh!important;overflow:auto!important;background:#32161b!important}dialog[data-studio-dialog-edit]{display:block!important;position:relative!important;inset:auto!important;margin:30px auto!important;max-width:calc(100% - 40px)!important;max-height:none!important;overflow:visible!important;opacity:1!important;visibility:visible!important;transform:none!important}';d.head.append(style);frame.contentWindow.scrollTo(0,0)}

function selectionPositionLocked(){return (alignmentSelection.length?alignmentSelection:[selected]).some(e=>e?.hasAttribute('data-studio-locked'))}
function lockedPositionMessage(){status('This selection contains a locked item. Unlock it in Properties before moving, resizing or deleting.',true)}
$('lock-element').onclick=()=>{if(!selected)return;const items=alignmentSelection.length?alignmentSelection:[selected],unlock=items.every(e=>e.hasAttribute('data-studio-locked'));for(const e of items)e.toggleAttribute('data-studio-locked',!unlock);checkpoint();fillInspector();status(unlock?'Selection unlocked.':'Selection locked against movement, resize and deletion. Save page to keep the lock.')};
const fillInspectorBeforeLock=fillInspector;fillInspector=function(){fillInspectorBeforeLock();const locked=!!selected&&selectionPositionLocked();$('lock-element').textContent=locked?'🔒 Unlock':'🔓 Lock';$('lock-element').setAttribute('aria-pressed',String(locked))};
